var SERIF = 'Georgia,"Times New Roman",serif';
var RED = '#e8483b', GOLD = '#ef9c14', GOLDPALE = '#ffd98a', GOLDINK = '#b07510';
var TAN = '#f8e3c5', BLKB = '#e9caa3', BLKA = '#f6a98f', GRAY = '#909090', INK = '#111';

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 900, 562);
draw.rect(900, 562).fill('#fff');

/* ---------- geometry of the incline ---------- */
var ANG = Math.atan2(131, 286);
var ANGDEG = ANG * 180 / Math.PI;
var U = { x: Math.cos(ANG), y: -Math.sin(ANG) };          // up-slope
var N = { x: -Math.sin(ANG), y: -Math.cos(ANG) };         // outward normal
function neg(d) { return { x: -d.x, y: -d.y }; }
function rotv(d, a) {
  a = a * Math.PI / 180;
  return { x: d.x * Math.cos(a) + d.y * Math.sin(a), y: -d.x * Math.sin(a) + d.y * Math.cos(a) };
}
var D = { x: 103, y: 92 };   // free-body dot (panel-local)

/* ---------- drawing helpers ---------- */
function arrow(g, x1, y1, x2, y2, color, w, hl) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1, ux = dx / L, uy = dy / L;
  var bx = x2 - ux * hl, by = y2 - uy * hl, hw = hl * 0.46;
  var grp = g.group();
  grp.line(x1, y1, bx + ux * 2, by + uy * 2).stroke({ color: color, width: w, linecap: 'butt' });
  grp.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(color);
  return grp;
}

function vecSym(g, x, yb, base, sub, size, color, halo) {
  var grp = g.group();
  var t = grp.plain(base).font({ family: SERIF, size: size, weight: 'bold' }).attr({ x: x, y: yb, fill: color });
  var bw = t.bbox().width; if (!bw || !isFinite(bw)) bw = size * 0.72;
  var total = bw, s = null;
  if (sub) {
    s = grp.plain(sub).font({ family: SERIF, size: size * 0.68, weight: 'bold' })
      .attr({ x: x + bw + 1, y: yb + size * 0.22, fill: color });
    var sw = s.bbox().width; if (!sw || !isFinite(sw)) sw = size * 0.8;
    total = bw + 1 + sw;
  }
  var ay = yb - size * 0.9, x2 = x + bw + 3;
  if (halo) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.4, 'stroke-linejoin': 'round' });
    if (s) s.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3, 'stroke-linejoin': 'round' });
    grp.line(x - 1, ay, x2 + 2, ay).stroke({ color: '#fff', width: 5, linecap: 'round' }).back();
  }
  grp.line(x + 0.5, ay, x2 - 2, ay).stroke({ color: color, width: 1.2 });
  grp.polygon([[x2 + 1.5, ay], [x2 - 2.5, ay - 2.3], [x2 - 2.5, ay + 2.3]]).fill(color);
  grp.data('w', total + 4);
  return grp;
}

/* ---------- vector data ---------- */
var VINFO = {
  'N_BA': { base: 'N', sub: 'BA', tip: 'N(BA): normal force exerted by B on A', pop: ['Normal force N\u20D7\u2009BA', 'Block B pushes block A perpendicular to the surface where they touch. It belongs only on A\u2019s free-body diagram; its third-law partner N\u20D7\u2009AB appears on B\u2019s diagram.'] },
  'T': { base: 'T', sub: '', tip: 'T: tension in the cord, up the slope', pop: ['Tension T\u20D7', 'The cord touches only block A, so tension acts only on A. This is why no tension arrow ever appears on block B\u2019s free-body diagram.'] },
  'f_BA': { base: 'f', sub: 'BA', tip: 'f(BA): friction exerted by B on A', pop: ['Friction f\u20D7\u2009BA', 'Friction from B acts on A along the contact surface, opposing the tendency of A to slide over B. Its partner f\u20D7\u2009AB acts on B in the opposite direction.'] },
  'w_A': { base: 'w', sub: 'A', tip: 'w(A): weight of block A', pop: ['Weight w\u20D7\u2009A', 'Earth pulls block A straight down with force w\u20D7\u2009A = m\u2090g. Gravity is a non-contact force, so it appears on A\u2019s diagram even though nothing touches A from below except B.'] },
  'N_B': { base: 'N', sub: 'B', tip: 'N(B): normal force from the incline on B', pop: ['Normal force N\u20D7\u2009B', 'The incline surface pushes block B perpendicular to the slope. Its third-law partner (B pushing on the incline) is not drawn, because it acts on the incline, not on B.'] },
  'f_AB': { base: 'f', sub: 'AB', tip: 'f(AB): friction exerted by A on B', pop: ['Friction f\u20D7\u2009AB', 'Block A drags on block B along their shared surface. It is the third-law partner of f\u20D7\u2009BA: equal magnitude, opposite direction, but drawn on B\u2019s diagram.'] },
  'f_B': { base: 'f', sub: 'B', tip: 'f(B): friction from the incline on B', pop: ['Friction f\u20D7\u2009B', 'The incline surface rubs on block B. This force is unrelated to the A\u2013B pair; it comes from a different contact, so it has its own partner acting on the incline.'] },
  'N_AB': { base: 'N', sub: 'AB', tip: 'N(AB): normal force exerted by A on B', pop: ['Normal force N\u20D7\u2009AB', 'Block A presses into block B, perpendicular to their contact surface. Equal and opposite to N\u20D7\u2009BA \u2014 but because it acts on a different body, the two never cancel.'] },
  'w_B': { base: 'w', sub: 'B', tip: 'w(B): weight of block B', pop: ['Weight w\u20D7\u2009B', 'Earth pulls block B straight down with w\u20D7\u2009B = m_Bg. Note it is B\u2019s weight alone \u2014 A\u2019s weight reaches B only through the contact force N\u20D7\u2009AB.'] }
};
var PAIR = { none: [], normal: ['N_BA', 'N_AB'], friction: ['f_BA', 'f_AB'] };

function vecsA(flip) {
  return [
    { k: 'N_BA', dir: N, len: 74, lx: 44, ly: 15 },
    { k: 'T', dir: U, len: 66, lx: 170, ly: 82 },
    { k: 'f_BA', dir: flip ? rotv(U, -16) : neg(U), len: 56, lx: flip ? 166 : 14, ly: flip ? 104 : 104 },
    { k: 'w_A', dir: { x: 0, y: 1 }, len: 58, lx: 114, ly: 146 }
  ];
}
function vecsB(flip) {
  var fab = flip ? neg(rotv(U, 18)) : rotv(U, 18);
  var fb = flip ? neg(U) : U;
  return [
    { k: 'N_B', dir: N, len: 74, lx: 44, ly: 15 },
    { k: 'f_AB', dir: fab, len: 52, lx: flip ? 58 : 118, ly: flip ? 138 : 46 },
    { k: 'f_B', dir: fb, len: 72, lx: flip ? 6 : 174, ly: flip ? 116 : 76 },
    { k: 'N_AB', dir: neg(N), len: 58, lx: 134, ly: 158 },
    { k: 'w_B', dir: { x: -0.16, y: 0.987 }, len: 60, lx: 42, ly: 158 }
  ];
}

var LEG_A = [
  { k: 'w_A', y: 30, text: 'weight of block A' },
  { k: 'T', y: 76, text: 'tension' },
  { k: 'N_BA', y: 122, text: 'normal force exerted by B on A' },
  { k: 'f_BA', y: 168, text: 'friction force exerted by B on A' }
];
var LEG_B = [
  { k: 'w_B', y: 26, text: 'weight of block B' },
  { k: 'N_AB', y: 64, text: 'normal force exerted by A on B' },
  { k: 'N_B', y: 102, text: 'normal force exerted by the incline plane on B' },
  { k: 'f_AB', y: 140, text: 'friction force exerted by A on B' },
  { k: 'f_B', y: 178, text: 'friction force exerted by the incline plane on B' }
];

/* ---------- state ---------- */
var state = { isolate: null, pair: 'none', flip: false };

/* ---------- panel construction ---------- */
function buildPanel(which, yOff) {
  var G = draw.group().translate(0, yOff);
  var P = { which: which, root: G };

  /* --- sketch --- */
  var sk = G.group();
  sk.polygon([[152, 199], [424.8, 74.2], [424.8, 199]]).fill(TAN);
  sk.line(146, 201.7, 430, 71.8).stroke({ color: GRAY, width: 2.6, linecap: 'round' });

  var bBc = { x: 251, y: 131.7 }, bAc = { x: 238.1, y: 103.5 };

  var bB = sk.group();
  bB.rect(52, 40).fill(BLKB).stroke({ color: '#7d7d7d', width: 1.2 }).center(bBc.x, bBc.y);
  bB.plain('B').font({ family: SERIF, size: 13, weight: 'bold', anchor: 'middle' })
    .attr({ x: bBc.x, y: bBc.y + 4.5, fill: '#3a3a3a' });
  bB.rotate(-ANGDEG, bBc.x, bBc.y);

  var bA = sk.group();
  bA.rect(36, 22).fill(BLKA).stroke({ color: '#d9846a', width: 1.2 }).center(bAc.x, bAc.y);
  bA.plain('A').font({ family: SERIF, size: 12, weight: 'bold', anchor: 'middle' })
    .attr({ x: bAc.x, y: bAc.y + 4.2, fill: '#5c2a1c' });
  bA.rotate(-ANGDEG, bAc.x, bAc.y);

  sk.line(254.5, 96, 428, 23).stroke({ color: '#111', width: 1.6 });

  var cap;
  if (which === 'a') {
    cap = sk.rect(50, 36).radius(14).center(bAc.x, bAc.y).fill('none')
      .stroke({ color: '#9a9a9a', width: 2.2 });
    cap.rotate(-ANGDEG, bAc.x, bAc.y);
  } else {
    cap = sk.rect(64, 50).radius(18).center(bBc.x, bBc.y).fill('none')
      .stroke({ color: '#9a9a9a', width: 2.2 });
    cap.rotate(-ANGDEG, bBc.x, bBc.y);
  }
  P.blockA = bA; P.blockB = bB; P.cap = cap;

  bA.css('cursor', 'pointer').on('mousemove', function (e) { showTooltip('Block A \u2014 click to isolate it', e); })
    .on('mouseleave', hideTooltip).on('click', function () { setIsolate(state.isolate === 'A' ? null : 'A'); });
  bB.css('cursor', 'pointer').on('mousemove', function (e) { showTooltip('Block B \u2014 click to isolate it', e); })
    .on('mouseleave', hideTooltip).on('click', function () { setIsolate(state.isolate === 'B' ? null : 'B'); });

  /* --- free-body diagram --- */
  var fb = G.group();
  fb.line(D.x - 100 * U.x, D.y - 100 * U.y, D.x + 22 * U.x, D.y + 22 * U.y)
    .stroke({ color: '#333', width: 1.4, dasharray: '7,5' });
  P.vecG = G.group();
  var dotG = G.group();
  dotG.circle(11).center(D.x, D.y).fill('#111');

  /* --- legend --- */
  var legend = G.group();
  var rows = (which === 'a') ? LEG_A : LEG_B;
  P.rows = {};
  rows.forEach(function (r) {
    var info = VINFO[r.k];
    var rg = legend.group();
    var sym = vecSym(rg, 442, r.y, info.base, info.sub, 14, INK, false);
    var w = parseFloat(sym.data('w')) || 26;
    rg.plain('=  ' + r.text).font({ family: SERIF, size: 14 })
      .attr({ x: 442 + w + 6, y: r.y, fill: INK });
    var bb = rg.bbox();
    var bg = rg.rect(bb.width + 12, bb.height + 8).radius(5).move(bb.x - 6, bb.y - 4)
      .fill(GOLD).opacity(0);
    bg.back();
    P.rows[r.k] = { g: rg, bg: bg };
    rg.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(info.tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup(info.pop[0], info.pop[1]); });
  });

  G.plain('(' + which + ')').font({ family: SERIF, size: 15, anchor: 'middle' })
    .attr({ x: 450, y: 232, fill: INK });

  return P;
}

var PA = buildPanel('a', 8);
var PB = buildPanel('b', 290);
var annG = draw.group();

/* ---------- vector rendering ---------- */
function drawVectors(P) {
  P.vecG.clear();
  var specs = (P.which === 'a') ? vecsA(state.flip) : vecsB(state.flip);
  specs.forEach(function (s) {
    var info = VINFO[s.k];
    var hl = PAIR[state.pair].indexOf(s.k) >= 0;
    var dim = (state.pair !== 'none') && !hl;
    var col = hl ? GOLD : RED;
    var tx = D.x + s.dir.x * s.len, ty = D.y + s.dir.y * s.len;
    var g = P.vecG.group();
    if (hl) g.line(D.x, D.y, tx, ty).stroke({ color: GOLDPALE, width: 12, linecap: 'round' }).opacity(0.8);
    arrow(g, D.x, D.y, tx, ty, col, 4.4, 14);
    vecSym(g, s.lx, s.ly, info.base, info.sub, 14, col, true);
    if (dim) g.opacity(0.22);
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) { showTooltip(info.tip, e); });
    g.on('mouseleave', hideTooltip);
    g.on('click', function () { showPopup(info.pop[0], info.pop[1]); });
  });
}

/* ---------- pair annotation in the gap between panels ---------- */
function drawAnnotation() {
  annG.clear();
  if (state.pair === 'none') return;
  var a = (state.pair === 'normal') ? ['N', 'BA', 'N', 'AB'] : ['f', 'BA', 'f', 'AB'];
  var x = 150, y = 272;
  var s1 = vecSym(annG, x, y, a[0], a[1], 14, GOLDINK, false);
  x += (parseFloat(s1.data('w')) || 26) + 3;
  var t1 = annG.plain('on A   and ').font({ family: SERIF, size: 13.5, style: 'italic' })
    .attr({ x: x, y: y, fill: GOLDINK });
  x += (t1.bbox().width || 70) + 4;
  var s2 = vecSym(annG, x, y, a[2], a[3], 14, GOLDINK, false);
  x += (parseFloat(s2.data('w')) || 26) + 3;
  annG.plain('on B  \u2014  equal magnitude, opposite direction, drawn on different free-body diagrams')
    .font({ family: SERIF, size: 13.5, style: 'italic' }).attr({ x: x, y: y, fill: GOLDINK });
  var bb = annG.bbox();
  annG.rect(bb.width + 14, bb.height + 8).radius(5).move(bb.x - 7, bb.y - 4)
    .fill('#fff').opacity(0.85).back();
}

/* ---------- master update ---------- */
function update() {
  drawVectors(PA);
  drawVectors(PB);
  drawAnnotation();

  PA.root.opacity(state.isolate === 'B' ? 0.18 : 1);
  PB.root.opacity(state.isolate === 'A' ? 0.18 : 1);
  PA.blockB.opacity(state.isolate === 'A' ? 0.28 : 1);
  PB.blockA.opacity(state.isolate === 'B' ? 0.28 : 1);
  PA.cap.opacity(state.isolate === 'B' ? 0.4 : 1);
  PB.cap.opacity(state.isolate === 'A' ? 0.4 : 1);

  var keys = PAIR[state.pair];
  [PA, PB].forEach(function (P) {
    for (var k in P.rows) {
      P.rows[k].bg.opacity(keys.indexOf(k) >= 0 ? 0.35 : 0);
    }
  });

  var bA = document.getElementById('isoABtn'), bB = document.getElementById('isoBBtn'),
    bN = document.getElementById('isoNoneBtn');
  if (bA) bA.className = (state.isolate === 'A') ? 'active' : '';
  if (bB) bB.className = (state.isolate === 'B') ? 'active' : '';
  if (bN) bN.className = (state.isolate === null) ? 'active' : '';
  var sv = document.getElementById('slidingVal');
  if (sv) sv.textContent = state.flip
    ? 'Now: A tends to slide up the slope \u2014 friction arrows reversed.'
    : 'Now: default tendency (as in the textbook figure).';
}

/* ---------- interactions ---------- */
function setIsolate(v) { state.isolate = v; update(); }
function trigger_isolateA() { setIsolate('A'); }
function trigger_isolateB() { setIsolate('B'); }
function trigger_isolateNone() { setIsolate(null); }
function toggle_contactPair(v) { state.pair = v; update(); }
function toggle_slidingTendency(on) { state.flip = !!on; update(); }
function showKeyInsight() {
