  if (bA) bA.className = (state.isolate === 'A') ? 'active' : '';
  if (bB) bB.className = (state.isolate === 'B') ? 'active' : '';
  if (bN) bN.className = (state.isolate === null) ? 'active' : '';
  var sv = document.getElementById('slidingVal');
  if (sv) sv.textContent = state.flip
    ? 'Now: A tends to slide up the slope \u2014 friction arrows reversed.'
    : 'Now: default tendency (as in the textbook figure).';
}

/* ---------- interactions ---------- */
function setIsolate(v) { state.isolate = v; update(); }
function trigger_isolateA() { setIsolate('A'); }
function trigger_isolateB() { setIsolate('B'); }
function trigger_isolateNone() { setIsolate(null); }
function toggle_contactPair(v) { state.pair = v; update(); }
function toggle_slidingTendency(on) { state.flip = !!on; update(); }
function showKeyInsight() {
  showPopup('Key insight',
    'Third-law partners like N\u20D7\u2009BA and N\u20D7\u2009AB are equal in magnitude and opposite in direction, but they always appear on different free-body diagrams. That is exactly why isolating one body at a time is the only reliable way to keep them straight \u2014 forces on different bodies can never cancel each other.');
}

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'The whole system',
    narr: 'Two blocks sit stacked on the incline, with a cord pulling block A up the slope. Before drawing any arrows, notice that A touches two things \u2014 the cord and block B \u2014 while B touches A and the incline.',
    st: { isolate: null, pair: 'none', flip: false }
  },
  {
    title: 'Isolate block A',
    narr: 'Click block A: everything else fades, leaving only the four forces acting on A \u2014 the tension T up the slope, the normal force N_BA from B, the friction f_BA from B, and A\u2019s weight w_A.',
    st: { isolate: 'A', pair: 'none', flip: false }
  },
  {
    title: 'Isolate block B',
    narr: 'Click block B instead. B feels five forces: its weight w_B, the incline\u2019s normal N_B and friction f_B, plus the normal N_AB and friction f_AB that block A presses back onto it. The tension never appears \u2014 the cord does not touch B.',
    st: { isolate: 'B', pair: 'none', flip: false }
  },
  {
    title: 'The normal-force pair',
    narr: 'Highlight the normal pair: N_BA pushes A away from the surface while N_AB presses down into it with equal magnitude. They are equal and opposite, but they live on different free-body diagrams, so they never cancel each other.',
    st: { isolate: null, pair: 'normal', flip: false }
  },
  {
    title: 'The friction pair',
    narr: 'Now highlight the friction pair: f_BA on A points down the slope while f_AB on B points up the slope. Same contact surface, same magnitude, opposite directions, acting on two different bodies.',
    st: { isolate: null, pair: 'friction', flip: false }
  },
  {
    title: 'Reverse the sliding tendency',
    narr: 'Flip the tendency so the cord wins and A tends to slide up over B. Every friction arrow reverses along its own surface \u2014 friction opposes relative sliding, so its direction is decided by the motion, not by the picture\u2019s geometry.',
    st: { isolate: null, pair: 'friction', flip: true }
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  state.isolate = s.st.isolate; state.pair = s.st.pair; state.flip = s.st.flip;
  var sel = document.getElementById('contactPairInput'); if (sel) sel.value = state.pair;
  var chk = document.getElementById('slidingTendencyInput'); if (chk) chk.checked = state.flip;
  var nar = document.getElementById('demoNarration'); if (nar) nar.textContent = s.narr;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (stepIdx + 1) + ' / ' + steps.length + ' \u00b7 ' + s.title;
  update();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Isolating each of two stacked blocks on an incline shows that a free-body diagram contains only the forces acting ON that body, and that the contact forces between the blocks are Newton's third-law pairs pointing in opposite directions on different bodies.
KEY INSIGHT (what students should walk away understanding): Third-law partners like N_BA and N_AB are equal and opposite but always appear on different free-body diagrams — which is exactly why isolating one body at a time is the only way to keep them straight.
DEMO STEPS: 6 guided steps — implement the step player in #ui

