// @FIGURE_CODE_BEGIN
var SERIF = 'Georgia,"Times New Roman",serif';
var RED = '#e8483b', GOLD = '#ef9c14', GOLDPALE = '#ffd98a', GOLDINK = '#a96d0b';
var TAN = '#f8e3c5', BLKB = '#e9caa3', BLKA = '#f6a98f', GRAY = '#909090', INK = '#111';

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, 900, 552);
draw.rect(900, 552).fill('#fff');

/* ---------- geometry of the incline ---------- */
var ANG = Math.atan2(129.9, 284);
var ANGDEG = ANG * 180 / Math.PI;
var U = { x: Math.cos(ANG), y: -Math.sin(ANG) };          // up-slope
var N = { x: -Math.sin(ANG), y: -Math.cos(ANG) };         // outward normal
function neg(d) { return { x: -d.x, y: -d.y }; }
function rotv(d, a) {                                      // +a = rotate toward "up" (CCW on screen)
  a = a * Math.PI / 180;
  return { x: d.x * Math.cos(a) + d.y * Math.sin(a), y: -d.x * Math.sin(a) + d.y * Math.cos(a) };
}
var D = { x: 103, y: 100 };   // free-body dot (panel-local)

/* ---------- drawing helpers ---------- */
function arrow(g, x1, y1, x2, y2, color, w, hl) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1, ux = dx / L, uy = dy / L;
  var bx = x2 - ux * hl, by = y2 - uy * hl, hw = hl * 0.46;
  var grp = g.group();
  grp.line(x1, y1, bx + ux * 2, by + uy * 2).stroke({ color: color, width: w, linecap: 'butt' });
  grp.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(color);
  return grp;
}

/* bold symbol with an overhead vector arrow; returns group, .data('w') = total width */
function vecSym(g, x, yb, base, sub, size, color, halo) {
  var grp = g.group();
  var t = grp.plain(base).font({ family: SERIF, size: size, weight: 'bold' })
    .attr({ x: x, y: yb, fill: color });
  var bw = t.bbox().width; if (!bw || !isFinite(bw)) bw = size * 0.72;
  var total = bw, s = null;
  if (sub) {
    s = grp.plain(sub).font({ family: SERIF, size: size * 0.68, weight: 'bold' })
      .attr({ x: x + bw + 1.5, y: yb + size * 0.24, fill: color });
    var sw = s.bbox().width; if (!sw || !isFinite(sw)) sw = size * 0.85;
    total = bw + 1.5 + sw;
  }
  var ay = yb - size * 0.92, x2 = x + bw + 3.5;
  if (halo) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4, 'stroke-linejoin': 'round' });
    if (s) s.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.4, 'stroke-linejoin': 'round' });
    grp.line(x - 1.5, ay, x2 + 3, ay).stroke({ color: '#fff', width: 6, linecap: 'round' }).back();
  }
  grp.line(x + 0.5, ay, x2 - 2.5, ay).stroke({ color: color, width: 1.5 });
  grp.polygon([[x2 + 2, ay], [x2 - 3, ay - 2.8], [x2 - 3, ay + 2.8]]).fill(color);
  grp.data('w', total + 5);
  return grp;
}

/* ---------- vector metadata ---------- */
var VINFO = {
  'N_BA': { base: 'N', sub: 'BA', tip: 'N(BA): normal force exerted by B on A', pop: ['Normal force N\u20D7\u2009BA', 'Block B pushes block A perpendicular to the surface where they touch. It belongs only on A\u2019s free-body diagram; its third-law partner N\u20D7\u2009AB appears on B\u2019s diagram.'] },
  'T': { base: 'T', sub: '', tip: 'T: tension in the cord, up the slope', pop: ['Tension T\u20D7', 'The cord touches only block A, so tension acts only on A. This is why no tension arrow ever appears on block B\u2019s free-body diagram.'] },
  'f_BA': { base: 'f', sub: 'BA', tip: 'f(BA): friction exerted by B on A', pop: ['Friction f\u20D7\u2009BA', 'Friction from B acts on A along the contact surface, opposing the tendency of A to slide over B. Its partner f\u20D7\u2009AB acts on B in the opposite direction.'] },
  'w_A': { base: 'w', sub: 'A', tip: 'w(A): weight of block A (straight down)', pop: ['Weight w\u20D7\u2009A', 'Earth pulls block A straight down with force w\u20D7\u2009A = m\u2090g. Gravity is a non-contact force, so it is always drawn vertically, never along the slope.'] },
  'N_B': { base: 'N', sub: 'B', tip: 'N(B): normal force from the incline on B', pop: ['Normal force N\u20D7\u2009B', 'The incline surface pushes block B perpendicular to the slope. Its third-law partner (B pushing on the incline) is not drawn, because it acts on the incline, not on B.'] },
  'f_AB': { base: 'f', sub: 'AB', tip: 'f(AB): friction exerted by A on B', pop: ['Friction f\u20D7\u2009AB', 'Block A drags on block B along their shared surface. It is the third-law partner of f\u20D7\u2009BA: equal magnitude, opposite direction, but drawn on B\u2019s diagram.'] },
  'f_B': { base: 'f', sub: 'B', tip: 'f(B): friction from the incline on B', pop: ['Friction f\u20D7\u2009B', 'The incline surface rubs on block B. This force is unrelated to the A\u2013B pair; it comes from a different contact, so it has its own partner acting on the incline.'] },
  'N_AB': { base: 'N', sub: 'AB', tip: 'N(AB): normal force exerted by A on B', pop: ['Normal force N\u20D7\u2009AB', 'Block A presses into block B, perpendicular to their contact surface. Equal and opposite to N\u20D7\u2009BA \u2014 but because it acts on a different body, the two never cancel.'] },
  'w_B': { base: 'w', sub: 'B', tip: 'w(B): weight of block B (straight down)', pop: ['Weight w\u20D7\u2009B', 'Earth pulls block B straight down with w\u20D7\u2009B = m_Bg. It is B\u2019s weight alone \u2014 A\u2019s weight reaches B only through the contact force N\u20D7\u2009AB.'] }
};
var PAIR = { none: [], normal: ['N_BA', 'N_AB'], friction: ['f_BA', 'f_AB'] };

/* ---------- force sets (weights ALWAYS vertical) ---------- */
function vecsA(flip) {
  return [
    { k: 'N_BA', dir: N, len: 72, lx: 56, ly: 27 },
    { k: 'T', dir: U, len: 76, lx: 178, ly: 80 },
    {
      k: 'f_BA', dir: flip ? rotv(U, -14) : neg(U), len: 60,
      lx: flip ? 170 : 6, ly: flip ? 106 : 110
    },
    { k: 'w_A', dir: { x: 0, y: 1 }, len: 58, lx: 111, ly: 152 }
  ];
}
function vecsB(flip) {
  var fabD = rotv(U, 26);
  return [
    { k: 'N_B', dir: N, len: 72, lx: 56, ly: 27 },
    {
      k: 'f_AB', dir: flip ? neg(fabD) : fabD, len: 56,
      lx: flip ? 12 : 116, ly: flip ? 167 : 44
    },
    {
      k: 'f_B', dir: flip ? neg(U) : U, len: 76,
      lx: flip ? 4 : 180, ly: flip ? 112 : 78
    },
    { k: 'N_AB', dir: neg(N), len: 60, lx: 124, ly: 177 },
    { k: 'w_B', dir: { x: 0, y: 1 }, len: 62, lx: 44, ly: 175 }
  ];
}

var LEG_A = [
  { k: 'w_A', y: 36, text: 'weight of block A' },
  { k: 'T', y: 82, text: 'tension' },
  { k: 'N_BA', y: 128, text: 'normal force exerted by B on A' },
  { k: 'f_BA', y: 174, text: 'friction force exerted by B on A' }
];
var LEG_B = [
  { k: 'w_B', y: 30, text: 'weight of block B' },
  { k: 'N_AB', y: 70, text: 'normal force exerted by A on B' },
  { k: 'N_B', y: 110, text: 'normal force exerted by the incline plane on B' },
  { k: 'f_AB', y: 150, text: 'friction force exerted by A on B' },
  { k: 'f_B', y: 190, text: 'friction force exerted by the incline plane on B' }
];

/* ---------- state ---------- */
var state = { isolate: null, pair: 'none', flip: false };

/* ---------- sketch geometry (blocks flush on the slope) ---------- */
var P0 = { x: 146, y: 201.7 };
function slopePt(s) { return { x: P0.x + U.x * s, y: P0.y + U.y * s }; }
var CONTACT = slopePt(118);                                   // where B meets the incline
var HB = 40, WB = 52, HA = 22, WA = 36;
var bBc = { x: CONTACT.x + N.x * (HB / 2), y: CONTACT.y + N.y * (HB / 2) };
var bAc = { x: CONTACT.x + N.x * (HB + HA / 2), y: CONTACT.y + N.y * (HB + HA / 2) };

/* ---------- panel construction ---------- */
function buildPanel(which, yOff) {
  var G = draw.group().translate(0, yOff);
  var P = { which: which, root: G };

  /* --- pictorial sketch --- */
  var sk = G.group();
  sk.polygon([[152, 199], [430, 71.8], [430, 199]]).fill(TAN);
  sk.line(146, 201.7, 432, 70.9).stroke({ color: GRAY, width: 2.6, linecap: 'round' });

  var bB = sk.group();
  bB.rect(WB, HB).fill(BLKB).stroke({ color: '#8a8a8a', width: 1.2 }).center(bBc.x, bBc.y);
  bB.plain('B').font({ family: SERIF, size: 15, weight: 'bold', anchor: 'middle' })
    .attr({ x: bBc.x, y: bBc.y + 5.2, fill: '#3a3a3a' });
  bB.rotate(-ANGDEG, bBc.x, bBc.y);

  var bA = sk.group();
  bA.rect(WA, HA).fill(BLKA).stroke({ color: '#d9846a', width: 1.2 }).center(bAc.x, bAc.y);
  bA.plain('A').font({ family: SERIF, size: 13, weight: 'bold', anchor: 'middle' })
    .attr({ x: bAc.x, y: bAc.y + 4.6, fill: '#5c2a1c' });
  bA.rotate(-ANGDEG, bAc.x, bAc.y);

  /* cord leaves A up-slope */
  var cs = { x: bAc.x + U.x * (WA / 2), y: bAc.y + U.y * (WA / 2) };
  sk.line(cs.x, cs.y, 428, 22).stroke({ color: '#111', width: 1.7 });

  var cap;
  if (which === 'a') {
    cap = sk.rect(WA + 11, HA + 11).radius(13).center(bAc.x, bAc.y).fill('none')
      .stroke({ color: '#9a9a9a', width: 2.3 });
    cap.rotate(-ANGDEG, bAc.x, bAc.y);
  } else {
    cap = sk.rect(WB + 13, HB + 12).radius(18).center(bBc.x, bBc.y).fill('none')
      .stroke({ color: '#9a9a9a', width: 2.3 });
    cap.rotate(-ANGDEG, bBc.x, bBc.y);
  }
  P.blockA = bA; P.blockB = bB; P.cap = cap;

  bA.css('cursor', 'pointer').on('mousemove', function (e) { showTooltip('Block A \u2014 click to isolate it', e); })
    .on('mouseleave', hideTooltip).on('click', function () { setIsolate(state.isolate === 'A' ? null : 'A'); });
  bB.css('cursor', 'pointer').on('mousemove', function (e) { showTooltip('Block B \u2014 click to isolate it', e); })
    .on('mouseleave', hideTooltip).on('click', function () { setIsolate(state.isolate === 'B' ? null : 'B'); });

  /* --- free-body diagram --- */
  var fb = G.group();
  fb.line(D.x - 96 * U.x, D.y - 96 * U.y, D.x + 32 * U.x, D.y + 32 * U.y)
