}

/* ---------- vector metadata ---------- */
var VINFO = {
  'N_BA': { base: 'N', sub: 'BA', tip: 'N(BA): normal force exerted by B on A', pop: ['Normal force N\u20D7\u2009BA', 'Block B pushes block A perpendicular to the surface where they touch. It belongs only on A\u2019s free-body diagram; its third-law partner N\u20D7\u2009AB appears on B\u2019s diagram.'] },
  'T': { base: 'T', sub: '', tip: 'T: tension in the cord, up the slope', pop: ['Tension T\u20D7', 'The cord touches only block A, so tension acts only on A. This is why no tension arrow ever appears on block B\u2019s free-body diagram.'] },
  'f_BA': { base: 'f', sub: 'BA', tip: 'f(BA): friction exerted by B on A', pop: ['Friction f\u20D7\u2009BA', 'Friction from B acts on A along the contact surface, opposing the tendency of A to slide over B. Its partner f\u20D7\u2009AB acts on B in the opposite direction.'] },
  'w_A': { base: 'w', sub: 'A', tip: 'w(A): weight of block A (straight down)', pop: ['Weight w\u20D7\u2009A', 'Earth pulls block A straight down with force w\u20D7\u2009A = m\u2090g. Gravity is a non-contact force, so it is always drawn vertically, never along the slope.'] },
  'N_B': { base: 'N', sub: 'B', tip: 'N(B): normal force from the incline on B', pop: ['Normal force N\u20D7\u2009B', 'The incline surface pushes block B perpendicular to the slope. Its third-law partner (B pushing on the incline) is not drawn, because it acts on the incline, not on B.'] },
  'f_AB': { base: 'f', sub: 'AB', tip: 'f(AB): friction exerted by A on B', pop: ['Friction f\u20D7\u2009AB', 'Block A drags on block B along their shared surface. It is the third-law partner of f\u20D7\u2009BA: equal magnitude, opposite direction, but drawn on B\u2019s diagram.'] },
  'f_B': { base: 'f', sub: 'B', tip: 'f(B): friction from the incline on B', pop: ['Friction f\u20D7\u2009B', 'The incline surface rubs on block B. This force is unrelated to the A\u2013B pair; it comes from a different contact, so it has its own partner acting on the incline.'] },
  'N_AB': { base: 'N', sub: 'AB', tip: 'N(AB): normal force exerted by A on B', pop: ['Normal force N\u20D7\u2009AB', 'Block A presses into block B, perpendicular to their contact surface. Equal and opposite to N\u20D7\u2009BA \u2014 but because it acts on a different body, the two never cancel.'] },
  'w_B': { base: 'w', sub: 'B', tip: 'w(B): weight of block B (straight down)', pop: ['Weight w\u20D7\u2009B', 'Earth pulls block B straight down with w\u20D7\u2009B = m_Bg. It is B\u2019s weight alone \u2014 A\u2019s weight reaches B only through the contact force N\u20D7\u2009AB.'] }
};
var PAIR = { none: [], normal: ['N_BA', 'N_AB'], friction: ['f_BA', 'f_AB'] };

/* ---------- force sets (weights ALWAYS vertical) ---------- */
function vecsA(flip) {
  return [
    { k: 'N_BA', dir: N, len: 72, lx: 56, ly: 27 },
    { k: 'T', dir: U, len: 76, lx: 178, ly: 80 },
    {
      k: 'f_BA', dir: flip ? rotv(U, -14) : neg(U), len: 60,
      lx: flip ? 170 : 6, ly: flip ? 106 : 110
    },
    { k: 'w_A', dir: { x: 0, y: 1 }, len: 58, lx: 111, ly: 152 }
  ];
}
function vecsB(flip) {
  var fabD = rotv(U, 26);
  return [
    { k: 'N_B', dir: N, len: 72, lx: 56, ly: 27 },
    {
      k: 'f_AB', dir: flip ? neg(fabD) : fabD, len: 56,
      lx: flip ? 12 : 116, ly: flip ? 167 : 44
    },
    {
      k: 'f_B', dir: flip ? neg(U) : U, len: 76,
      lx: flip ? 4 : 180, ly: flip ? 112 : 78
    },
    { k: 'N_AB', dir: neg(N), len: 60, lx: 124, ly: 177 },
    { k: 'w_B', dir: { x: 0, y: 1 }, len: 62, lx: 44, ly: 175 }
  ];
}

var LEG_A = [
  { k: 'w_A', y: 36, text: 'weight of block A' },
  { k: 'T', y: 82, text: 'tension' },
  { k: 'N_BA', y: 128, text: 'normal force exerted by B on A' },
  { k: 'f_BA', y: 174, text: 'friction force exerted by B on A' }
];
var LEG_B = [
  { k: 'w_B', y: 30, text: 'weight of block B' },
  { k: 'N_AB', y: 70, text: 'normal force exerted by A on B' },
  { k: 'N_B', y: 110, text: 'normal force exerted by the incline plane on B' },
  { k: 'f_AB', y: 150, text: 'friction force exerted by A on B' },
  { k: 'f_B', y: 190, text: 'friction force exerted by the incline plane on B' }
];

/* ---------- state ---------- */
var state = { isolate: null, pair: 'none', flip: false };

/* ---------- sketch geometry (blocks flush on the slope) ---------- */
var P0 = { x: 146, y: 201.7 };
function slopePt(s) { return { x: P0.x + U.x * s, y: P0.y + U.y * s }; }
var CONTACT = slopePt(118);                                   // where B meets the incline
var HB = 40, WB = 52, HA = 22, WA = 36;
var bBc = { x: CONTACT.x + N.x * (HB / 2), y: CONTACT.y + N.y * (HB / 2) };
var bAc = { x: CONTACT.x + N.x * (HB + HA / 2), y: CONTACT.y + N.y * (HB + HA / 2) };

/* ---------- panel construction ---------- */
function buildPanel(which, yOff) {
  var G = draw.group().translate(0, yOff);
  var P = { which: which, root: G };

  /* --- pictorial sketch --- */
  var sk = G.group();
  sk.polygon([[152, 199], [430, 71.8], [430, 199]]).fill(TAN);
  sk.line(146, 201.7, 432, 70.9).stroke({ color: GRAY, width: 2.6, linecap: 'round' });

  var bB = sk.group();
  bB.rect(WB, HB).fill(BLKB).stroke({ color: '#8a8a8a', width: 1.2 }).center(bBc.x, bBc.y);
  bB.plain('B').font({ family: SERIF, size: 15, weight: 'bold', anchor: 'middle' })
    .attr({ x: bBc.x, y: bBc.y + 5.2, fill: '#3a3a3a' });
  bB.rotate(-ANGDEG, bBc.x, bBc.y);

  var bA = sk.group();
  bA.rect(WA, HA).fill(BLKA).stroke({ color: '#d9846a', width: 1.2 }).center(bAc.x, bAc.y);
  bA.plain('A').font({ family: SERIF, size: 13, weight: 'bold', anchor: 'middle' })
    .attr({ x: bAc.x, y: bAc.y + 4.6, fill: '#5c2a1c' });
  bA.rotate(-ANGDEG, bAc.x, bAc.y);

  /* cord leaves A up-slope */
  var cs = { x: bAc.x + U.x * (WA / 2), y: bAc.y + U.y * (WA / 2) };
  sk.line(cs.x, cs.y, 428, 22).stroke({ color: '#111', width: 1.7 });

  var cap;
  if (which === 'a') {
    cap = sk.rect(WA + 11, HA + 11).radius(13).center(bAc.x, bAc.y).fill('none')
      .stroke({ color: '#9a9a9a', width: 2.3 });
    cap.rotate(-ANGDEG, bAc.x, bAc.y);
  } else {
    cap = sk.rect(WB + 13, HB + 12).radius(18).center(bBc.x, bBc.y).fill('none')
      .stroke({ color: '#9a9a9a', width: 2.3 });
    cap.rotate(-ANGDEG, bBc.x, bBc.y);
  }
  P.blockA = bA; P.blockB = bB; P.cap = cap;

  bA.css('cursor', 'pointer').on('mousemove', function (e) { showTooltip('Block A \u2014 click to isolate it', e); })
    .on('mouseleave', hideTooltip).on('click', function () { setIsolate(state.isolate === 'A' ? null : 'A'); });
  bB.css('cursor', 'pointer').on('mousemove', function (e) { showTooltip('Block B \u2014 click to isolate it', e); })
    .on('mouseleave', hideTooltip).on('click', function () { setIsolate(state.isolate === 'B' ? null : 'B'); });

  /* --- free-body diagram --- */
  var fb = G.group();
  fb.line(D.x - 96 * U.x, D.y - 96 * U.y, D.x + 32 * U.x, D.y + 32 * U.y)
    .stroke({ color: '#333', width: 1.5, dasharray: '8,5.5' });
  P.vecG = G.group();
  G.group().circle(12).center(D.x, D.y).fill('#111');

  /* --- legend --- */
  var legend = G.group();
  var rows = (which === 'a') ? LEG_A : LEG_B;
  P.rows = {};
  rows.forEach(function (r) {
    var info = VINFO[r.k];
    var rg = legend.group();
    var sym = vecSym(rg, 446, r.y, info.base, info.sub, 17, INK, false);
    var w = parseFloat(sym.data('w')) || 30;
    rg.plain('=  ' + r.text).font({ family: SERIF, size: 16.5 })
      .attr({ x: 446 + w + 7, y: r.y, fill: INK });
    var bb = rg.bbox();
    var bg = rg.rect(bb.width + 14, bb.height + 9).radius(5).move(bb.x - 7, bb.y - 4.5)
      .fill(GOLD).opacity(0);
    bg.back();
    P.rows[r.k] = { g: rg, bg: bg };
    rg.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(info.tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup(info.pop[0], info.pop[1]); });
  });

  G.plain('(' + which + ')').font({ family: SERIF, size: 17, anchor: 'middle' })
    .attr({ x: 452, y: 233, fill: INK });

  return P;
}

var PA = buildPanel('a', 6);
var PB = buildPanel('b', 288);
var annG = draw.group();

/* ---------- vector rendering ---------- */
function drawVectors(P) {
  P.vecG.clear();
  var specs = (P.which === 'a') ? vecsA(state.flip) : vecsB(state.flip);
  specs.forEach(function (s) {
    var info = VINFO[s.k];
    var hl = PAIR[state.pair].indexOf(s.k) >= 0;
    var dim = (state.pair !== 'none') && !hl;
    var col = hl ? GOLD : RED;
    var tx = D.x + s.dir.x * s.len, ty = D.y + s.dir.y * s.len;
    var g = P.vecG.group();
    if (hl) g.line(D.x, D.y, tx, ty).stroke({ color: GOLDPALE, width: 13, linecap: 'round' }).opacity(0.8);
    arrow(g, D.x, D.y, tx, ty, col, 4.6, 15);
    vecSym(g, s.lx, s.ly, info.base, info.sub, 16.5, col, true);
    if (dim) g.opacity(0.22);
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) { showTooltip(info.tip, e); });
    g.on('mouseleave', hideTooltip);
    g.on('click', function () { showPopup(info.pop[0], info.pop[1]); });
  });
}

/* ---------- pair annotation in the gap between panels ---------- */
function drawAnnotation() {
  annG.clear();
  if (state.pair === 'none') return;
  var a = (state.pair === 'normal') ? ['N', 'BA', 'N', 'AB'] : ['f', 'BA', 'f', 'AB'];
  var x = 150, y = 268;
  var s1 = vecSym(annG, x, y, a[0], a[1], 16, GOLDINK, false);
  x += (parseFloat(s1.data('w')) || 30) + 4;
  var t1 = annG.plain('on A   and ').font({ family: SERIF, size: 15.5, style: 'italic' })
    .attr({ x: x, y: y, fill: GOLDINK });
  x += (t1.bbox().width || 80) + 5;
  var s2 = vecSym(annG, x, y, a[2], a[3], 16, GOLDINK, false);
  x += (parseFloat(s2.data('w')) || 30) + 4;
  annG.plain('on B  \u2014  equal magnitude, opposite direction, different free-body diagrams')
    .font({ family: SERIF, size: 15.5, style: 'italic' }).attr({ x: x, y: y, fill: GOLDINK });
  var bb = annG.bbox();
  annG.rect(bb.width + 16, bb.height + 9).radius(5).move(bb.x - 8, bb.y - 4.5)
    .fill('#fff').opacity(0.88).back();
}

/* ---------- master update ---------- */
function update() {
  drawVectors(PA);
  drawVectors(PB);
  drawAnnotation();

  PA.root.opacity(state.isolate === 'B' ? 0.18 : 1);
  PB.root.opacity(state.isolate === 'A' ? 0.18 : 1);
  PA.blockB.opacity(state.isolate === 'A' ? 0.28 : 1);
  PB.blockA.opacity(state.isolate === 'B' ? 0.28 : 1);
  PA.cap.opacity(state.isolate === 'B' ? 0.4 : 1);
  PB.cap.opacity(state.isolate === 'A' ? 0.4 : 1);

  var keys = PAIR[state.pair];
  [PA, PB].forEach(function (P) {
    for (var k in P.rows) P.rows[k].bg.opacity(keys.indexOf(k) >= 0 ? 0.35 : 0);
  });

  var bA = document.getElementById('isoABtn'), bB = document.getElementById('isoBBtn'),
    bN = document.getElementById('isoNoneBtn');
  if (bA) bA.className = (state.isolate === 'A') ? 'active' : '';
  if (bB) bB.className = (state.isolate === 'B') ? 'active' : '';
  if (bN) bN.className = (state.isolate === null) ? 'active' : '';
  var sv = document.getElementById('slidingVal');
  if (sv) sv.textContent = state.flip
    ? 'Now: A tends to slide up the slope \u2014 friction arrows reversed.'
    : 'Now: default tendency (as in the textbook figure).';
}

/* ---------- interactions ---------- */
function setIsolate(v) { state.isolate = v; update(); }
function trigger_isolateA() { setIsolate('A'); }
function trigger_isolateB() { setIsolate('B'); }
function trigger_isolateNone() { setIsolate(null); }
function toggle_contactPair(v) { state.pair = v; update(); }
function toggle_slidingTendency(on) { state.flip = !!on; update(); }
function showKeyInsight() {
  showPopup('Key insight',
    'Third-law partners like N\u20D7\u2009BA and N\u20D7\u2009AB are equal in magnitude and opposite in direction, but they always appear on different free-body diagrams. That is exactly why isolating one body at a time is the only reliable way to keep them straight \u2014 forces on different bodies can never cancel each other.');
}

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'The whole system',
    narr: 'Two blocks sit stacked on the incline, with a cord pulling block A up the slope. Before drawing any arrows, notice that A touches two things \u2014 the cord and block B \u2014 while B touches A and the incline.',
    st: { isolate: null, pair: 'none', flip: false }
  },
  {
    title: 'Isolate block A',
    narr: 'Click block A: everything else fades, leaving only the four forces acting on A \u2014 the tension T up the slope, the normal force N_BA from B, the friction f_BA from B, and A\u2019s weight w_A straight down.',
    st: { isolate: 'A', pair: 'none', flip: false }
  },
  {
    title: 'Isolate block B',
    narr: 'Click block B instead. B feels five forces: its weight w_B, the incline\u2019s normal N_B and friction f_B, plus the normal N_AB and friction f_AB that block A presses back onto it. The tension never appears \u2014 the cord does not touch B.',
    st: { isolate: 'B', pair: 'none', flip: false }
  },
  {
    title: 'The normal-force pair',
    narr: 'Highlight the normal pair: N_BA pushes A away from the surface while N_AB presses down into it with equal magnitude. They are equal and opposite, but they live on different free-body diagrams, so they never cancel each other.',
    st: { isolate: null, pair: 'normal', flip: false }
  },
  {
    title: 'The friction pair',
    narr: 'Now highlight the friction pair: f_BA on A points down the slope while f_AB on B points up the slope. Same contact surface, same magnitude, opposite directions, acting on two different bodies.',
    st: { isolate: null, pair: 'friction', flip: false }
  },
  {
    title: 'Reverse the sliding tendency',
    narr: 'Flip the tendency so the cord wins and A tends to slide up over B. Every friction arrow reverses along its own surface, while the normals and the vertical weights are unchanged \u2014 friction direction is set by the relative sliding, not by the picture.',
    st: { isolate: null, pair: 'friction', flip: true }
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  state.isolate = s.st.isolate; state.pair = s.st.pair; state.flip = s.st.flip;
  var sel = document.getElementById('contactPairInput'); if (sel) sel.value = state.pair;
  var chk = document.getElementById('slidingTendencyInput'); if (chk) chk.checked = state.flip;
  var nar = document.getElementById('demoNarration'); if (nar) nar.textContent = s.narr;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (stepIdx + 1) + ' / ' + steps.length + ' \u00b7 ' + s.title;
  update();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Isolating each of two stacked blocks on an incline shows that a free-body diagram contains only the forces acting ON that body, and that the contact forces between the blocks are Newton's third-law pairs pointing in opposite directions on different bodies.
KEY INSIGHT (what students should walk away understanding): Third-law partners like N_BA and N_AB are equal and opposite but always appear on different free-body diagrams — which is exactly why isolating one body at a time is the only way to keep them straight.
DEMO STEPS: 6 guided steps — implement the step player in #ui

