<!-- @FIGURE_UI_BEGIN -->
<strong style="font-size:12.5px">Stacked blocks on an incline</strong>
<p id="demoNarration" style="margin:0;font-size:11.5px;line-height:1.5;color:#1a1a1a"></p>
