  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;flex:1;text-align:center"></span>
  <button onclick="nextStep()">▶</button>
</span>
<span style="display:block;height:1px;background:#dcdfe3;margin:4px 0"></span>
<span style="font-size:11.5px;font-weight:bold">Isolate one body (or click a block)</span>
<span style="display:flex;gap:4px;flex-wrap:wrap">
  <button id="isoABtn" onclick="trigger_isolateA()">Block A</button>
  <button id="isoBBtn" onclick="trigger_isolateB()">Block B</button>
  <button id="isoNoneBtn" onclick="trigger_isolateNone()">Show both</button>
</span>
<label>Highlight third-law pair:
  <select id="contactPairInput" onchange="toggle_contactPair(this.value)">
    <option value="none">None</option>
    <option value="normal">Normal pair (N_BA / N_AB)</option>
    <option value="friction">Friction pair (f_BA / f_AB)</option>
  </select>
</label>
<label>Relative sliding tendency of A on B:
  <select id="slidingTendencyInput" onchange="toggle_slidingTendency(this.value)">
    <option value="up">A tends to slide up the slope (as drawn)</option>
    <option value="down">A tends to slide down the slope</option>
  </select>
</label>
<span id="slidingVal" style="font-size:11px;color:#444;line-height:1.45"></span>
<button onclick="showKeyInsight()">Key insight</button>
<span style="font-size:10.5px;color:#777;line-height:1.4">Hover any red arrow or legend line for its meaning; click it for a full explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var SERIF = 'Georgia,"Times New Roman",serif';
var RED = '#e8483b', GOLD = '#ef9c14', GOLDPALE = '#ffd98a', GOLDINK = '#a5690a';
var TAN = '#f8e3c5', BLKB = '#e9caa3', BLKA = '#f6a98f', GRAY = '#8f8f8f', INK = '#111';

var VBW = 800, VBH = 494;
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
draw.viewbox(0, 0, VBW, VBH);
draw.rect(VBW, VBH).fill('#fff');

/* ---------- incline geometry ---------- */
var ANG = Math.atan2(80, 174);                 // ~24.7 degrees
var ANGDEG = ANG * 180 / Math.PI;
var U = { x: Math.cos(ANG), y: -Math.sin(ANG) };   // up-slope
var N = { x: -Math.sin(ANG), y: -Math.cos(ANG) };  // outward normal
function neg(d) { return { x: -d.x, y: -d.y }; }
function rotv(d, a) {                               // +a tilts the vector further "up"
  a = a * Math.PI / 180;
  return { x: d.x * Math.cos(a) + d.y * Math.sin(a), y: -d.x * Math.sin(a) + d.y * Math.cos(a) };
}
var D = { x: 88, y: 100 };                          // free-body dot (panel-local)

/* ---------- drawing helpers ---------- */
function arrow(g, x1, y1, x2, y2, color, w, hl) {
  var dx = x2 - x1, dy = y2 - y1, L = Math.hypot(dx, dy) || 1, ux = dx / L, uy = dy / L;
  var bx = x2 - ux * hl, by = y2 - uy * hl, hw = hl * 0.46;
  var grp = g.group();
  grp.line(x1, y1, bx + ux * 2, by + uy * 2).stroke({ color: color, width: w, linecap: 'butt' });
  grp.polygon([[x2, y2], [bx - uy * hw, by + ux * hw], [bx + uy * hw, by - ux * hw]]).fill(color);
  return grp;
}

/* bold symbol with an overhead vector arrow; .data('w') = total advance width */
function vecSym(g, x, yb, base, sub, size, color, halo) {
  var grp = g.group();
  var t = grp.plain(base).font({ family: SERIF, size: size, weight: 'bold' })
    .attr({ x: x, y: yb, fill: color });
  var bw = t.bbox().width; if (!bw || !isFinite(bw)) bw = size * 0.72;
  var total = bw, s = null;
  if (sub) {
    s = grp.plain(sub).font({ family: SERIF, size: size * 0.68, weight: 'bold' })
      .attr({ x: x + bw + 1.5, y: yb + size * 0.25, fill: color });
    var sw = s.bbox().width; if (!sw || !isFinite(sw)) sw = size * 0.85;
    total = bw + 1.5 + sw;
  }
  var ay = yb - size * 0.94, x2 = x + bw + 3.5;
  if (halo) {
    t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4.4, 'stroke-linejoin': 'round' });
    if (s) s.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.6, 'stroke-linejoin': 'round' });
    grp.line(x - 1.5, ay, x2 + 3, ay).stroke({ color: '#fff', width: 6.5, linecap: 'round' }).back();
  }
  grp.line(x + 0.5, ay, x2 - 2.5, ay).stroke({ color: color, width: 1.6 });
  grp.polygon([[x2 + 2, ay], [x2 - 3, ay - 2.9], [x2 - 3, ay + 2.9]]).fill(color);
  grp.data('w', total + 5);
  return grp;
}

/* ---------- vector metadata ---------- */
var VINFO = {
  'N_BA': {
    base: 'N', sub: 'BA', tip: 'N\u20D7 BA: normal force exerted by B on A',
    pop: ['Normal force N\u20D7\u2009BA', 'Block B pushes block A perpendicular to the surface where they touch. It belongs only on A\u2019s free-body diagram; its third-law partner N\u20D7\u2009AB appears on B\u2019s diagram.']
  },
  'T': {
    base: 'T', sub: '', tip: 'T\u20D7: tension in the cord, up the slope',
    pop: ['Tension T\u20D7', 'The cord touches only block A, so tension acts only on A. This is why no tension arrow ever appears on block B\u2019s free-body diagram.']
  },
  'f_BA': {
    base: 'f', sub: 'BA', tip: 'f\u20D7 BA: friction exerted by B on A, along the A\u2013B surface',
    pop: ['Friction f\u20D7\u2009BA', 'Friction from B acts on A along their contact surface, opposing the tendency of A to slide over B. Here the cord pulls A up the slope, so A tends to slide up over B and f\u20D7\u2009BA points down the slope. (When it would overlap T\u20D7 it is drawn slightly off the surface line for clarity.)']
  },
  'w_A': {
    base: 'w', sub: 'A', tip: 'w\u20D7 A: weight of block A (straight down)',
    pop: ['Weight w\u20D7\u2009A', 'Earth pulls block A straight down with force w\u20D7\u2009A = m_A g. Gravity is a non-contact force, so it is always drawn vertically, never along the slope.']
  },
  'N_B': {
    base: 'N', sub: 'B', tip: 'N\u20D7 B: normal force from the incline plane on B',
    pop: ['Normal force N\u20D7\u2009B', 'The incline surface pushes block B perpendicular to the slope. Its third-law partner (B pushing on the incline) is not drawn, because it acts on the incline, not on B.']
  },
  'f_AB': {
    base: 'f', sub: 'AB', tip: 'f\u20D7 AB: friction exerted by A on B, along the A\u2013B surface',
    pop: ['Friction f\u20D7\u2009AB', 'Block A drags on block B along their shared surface. It is the third-law partner of f\u20D7\u2009BA: equal magnitude, opposite direction, but drawn on B\u2019s diagram. It really acts parallel to the contact surface; it is tilted slightly here only so it does not overlap f\u20D7\u2009B.']
  },
  'f_B': {
    base: 'f', sub: 'B', tip: 'f\u20D7 B: friction from the incline plane on B',
    pop: ['Friction f\u20D7\u2009B', 'The incline surface rubs on block B. This comes from a different contact than the A\u2013B pair, so changing how A tends to slide on B does not by itself reverse this arrow.']
  },
  'N_AB': {
    base: 'N', sub: 'AB', tip: 'N\u20D7 AB: normal force exerted by A on B',
    pop: ['Normal force N\u20D7\u2009AB', 'Block A presses into block B, perpendicular to their contact surface. Equal and opposite to N\u20D7\u2009BA \u2014 but because it acts on a different body, the two never cancel.']
  },
  'w_B': {
    base: 'w', sub: 'B', tip: 'w\u20D7 B: weight of block B (straight down)',
    pop: ['Weight w\u20D7\u2009B', 'Earth pulls block B straight down with w\u20D7\u2009B = m_B g. It is B\u2019s weight alone \u2014 A\u2019s weight reaches B only through the contact force N\u20D7\u2009AB.']
  }
};
var PAIR = { none: [], normal: ['N_BA', 'N_AB'], friction: ['f_BA', 'f_AB'] };

/* ---------- force sets (weights ALWAYS vertical) ---------- */
function vecsA(flip) {
  return [
    { k: 'N_BA', dir: N, len: 66, lx: 46, ly: 30 },
    { k: 'T', dir: U, len: 70, lx: 154, ly: 92 },
    {
      k: 'f_BA', dir: flip ? rotv(U, -16) : neg(U), len: flip ? 50 : 55,
      lx: flip ? 132 : 8, ly: flip ? 116 : 112
    },
    { k: 'w_A', dir: { x: 0, y: 1 }, len: 54, lx: 96, ly: 146 }
  ];
}
function vecsB(flip) {
  var fab = rotv(U, 22);
  return [
    { k: 'N_B', dir: N, len: 66, lx: 46, ly: 30 },
    {
      k: 'f_AB', dir: flip ? neg(fab) : fab, len: 52,
      lx: flip ? 4 : 118, ly: flip ? 150 : 50
    },
    { k: 'f_B', dir: U, len: 70, lx: 154, ly: 92 },
    { k: 'N_AB', dir: neg(N), len: 56, lx: 110, ly: 176 },
    { k: 'w_B', dir: { x: 0, y: 1 }, len: 60, lx: 36, ly: 172 }
  ];
}

var LEG_A = [
  { k: 'w_A', y: 40, text: 'weight of block A' },
  { k: 'T', y: 82, text: 'tension' },
  { k: 'N_BA', y: 124, text: 'normal force exerted by B on A' },
  { k: 'f_BA', y: 166, text: 'friction force exerted by B on A' }
];
var LEG_B = [
  { k: 'w_B', y: 26, text: 'weight of block B' },
  { k: 'N_AB', y: 66, text: 'normal force exerted by A on B' },
  { k: 'N_B', y: 106, text: 'normal force exerted by the incline plane on B' },
  { k: 'f_AB', y: 146, text: 'friction force exerted by A on B' },
  { k: 'f_B', y: 186, text: 'friction force exerted by the incline plane on B' }
];
var LEGX = 330, LEGF = 17;

/* ---------- state ---------- */
var state = { isolate: null, pair: 'none', flip: false };

/* ---------- sketch geometry ---------- */
var P0 = { x: 146, y: 199 };
var CONTACT = { x: P0.x + U.x * 88, y: P0.y + U.y * 88 };
var HB = 34, WB = 46, HA = 19, WA = 30;
var bBc = { x: CONTACT.x + N.x * (HB / 2), y: CONTACT.y + N.y * (HB / 2) };
var bAc = { x: CONTACT.x + N.x * (HB + HA / 2), y: CONTACT.y + N.y * (HB + HA / 2) };

/* ---------- panel construction ---------- */
function buildPanel(which, yOff) {
  var G = draw.group().translate(0, yOff);
  var P = { which: which, root: G };

  /* --- pictorial sketch --- */
  var sk = G.group();
  sk.polygon([[152, 194], [322, 116], [322, 194]]).fill(TAN);
  sk.line(146, 199, 324, 117).stroke({ color: GRAY, width: 2.4, linecap: 'round' });

  var bB = sk.group();
  bB.rect(WB, HB).fill(BLKB).stroke({ color: '#8a8a8a', width: 1.1 }).center(bBc.x, bBc.y);
  bB.plain('B').font({ family: SERIF, size: 14, weight: 'bold', anchor: 'middle' })
    .attr({ x: bBc.x, y: bBc.y + 5, fill: '#3a3a3a' });
  bB.rotate(-ANGDEG, bBc.x, bBc.y);

  var bA = sk.group();
  bA.rect(WA, HA).fill(BLKA).stroke({ color: '#d9846a', width: 1.1 }).center(bAc.x, bAc.y);
  bA.plain('A').font({ family: SERIF, size: 12, weight: 'bold', anchor: 'middle' })
    .attr({ x: bAc.x, y: bAc.y + 4.2, fill: '#5c2a1c' });
  bA.rotate(-ANGDEG, bAc.x, bAc.y);

  var cs = { x: bAc.x + U.x * (WA / 2), y: bAc.y + U.y * (WA / 2) };
  sk.line(cs.x, cs.y, 318, 44).stroke({ color: '#111', width: 1.6 });

  var cap;
  if (which === 'a') {
    cap = sk.rect(WA + 10, HA + 10).radius(11).center(bAc.x, bAc.y).fill('none')
      .stroke({ color: '#9a9a9a', width: 2.1 });
    cap.rotate(-ANGDEG, bAc.x, bAc.y);
  } else {
    cap = sk.rect(WB + 11, HB + 11).radius(15).center(bBc.x, bBc.y).fill('none')
      .stroke({ color: '#9a9a9a', width: 2.1 });
    cap.rotate(-ANGDEG, bBc.x, bBc.y);
  }
  P.blockA = bA; P.blockB = bB; P.cap = cap;

  bA.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Block A \u2014 click to isolate it', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { setIsolate(state.isolate === 'A' ? null : 'A'); });
  bB.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Block B \u2014 click to isolate it', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { setIsolate(state.isolate === 'B' ? null : 'B'); });

  /* --- free-body diagram --- */
  G.line(D.x - 84 * U.x, D.y - 84 * U.y, D.x + 32 * U.x, D.y + 32 * U.y)
    .stroke({ color: '#333', width: 1.5, dasharray: '8,5.5' });
  P.vecG = G.group();
  G.circle(11).center(D.x, D.y).fill('#111');

  /* --- legend --- */
  var legend = G.group();
  var rows = (which === 'a') ? LEG_A : LEG_B;
  P.rows = {};
  rows.forEach(function (r) {
    var info = VINFO[r.k];
    var rg = legend.group();
    var sym = vecSym(rg, LEGX, r.y, info.base, info.sub, LEGF, INK, false);
    var w = parseFloat(sym.data('w')) || 30;
    rg.plain('=  ' + r.text).font({ family: SERIF, size: LEGF })
      .attr({ x: LEGX + w + 6, y: r.y, fill: INK });
    var bb = rg.bbox();
    var bg = rg.rect(bb.width + 14, bb.height + 9).radius(5).move(bb.x - 7, bb.y - 4.5)
      .fill(GOLD).opacity(0);
    bg.back();
    P.rows[r.k] = { g: rg, bg: bg };
    rg.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(info.tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup(info.pop[0], info.pop[1]); });
  });

  G.plain('(' + which + ')').font({ family: SERIF, size: 18, anchor: 'middle' })
    .attr({ x: 390, y: 228, fill: INK });

  return P;
}

var PA = buildPanel('a', 4);
var PB = buildPanel('b', 250);
var annG = draw.group();

/* ---------- vector rendering ---------- */
function drawVectors(P) {
  P.vecG.clear();
  var specs = (P.which === 'a') ? vecsA(state.flip) : vecsB(state.flip);
  specs.forEach(function (s) {
    var info = VINFO[s.k];
    var hl = PAIR[state.pair].indexOf(s.k) >= 0;
    var dim = (state.pair !== 'none') && !hl;
    var col = hl ? GOLD : RED;
    var tx = D.x + s.dir.x * s.len, ty = D.y + s.dir.y * s.len;
    var g = P.vecG.group();
    if (hl) g.line(D.x, D.y, tx, ty).stroke({ color: GOLDPALE, width: 12.5, linecap: 'round' }).opacity(0.8);
    arrow(g, D.x, D.y, tx, ty, col, 4.4, 14);
    vecSym(g, s.lx, s.ly, info.base, info.sub, 17, col, true);
    if (dim) g.opacity(0.22);
    g.css('cursor', 'pointer');
    g.on('mousemove', function (e) { showTooltip(info.tip, e); });
    g.on('mouseleave', hideTooltip);
    g.on('click', function () { showPopup(info.pop[0], info.pop[1]); });
  });
}

/* ---------- pair annotation in the gap between panels ---------- */
function drawAnnotation() {
  annG.clear();
  if (state.pair === 'none') return;
  var a = (state.pair === 'normal') ? ['N', 'BA', 'N', 'AB'] : ['f', 'BA', 'f', 'AB'];
  var x = 26, y = 254, fs = 15.5;
  var s1 = vecSym(annG, x, y, a[0], a[1], 15.5, GOLDINK, false);
  x += (parseFloat(s1.data('w')) || 30) + 4;
  var t1 = annG.plain('on A   and ').font({ family: SERIF, size: fs, style: 'italic' })
    .attr({ x: x, y: y, fill: GOLDINK });
  x += (t1.bbox().width || 78) + 5;
  var s2 = vecSym(annG, x, y, a[2], a[3], 15.5, GOLDINK, false);
  x += (parseFloat(s2.data('w')) || 30) + 4;
  annG.plain('on B  \u2014  equal magnitude, opposite direction, different free-body diagrams')
    .font({ family: SERIF, size: fs, style: 'italic' }).attr({ x: x, y: y, fill: GOLDINK });
  var bb = annG.bbox();
  annG.rect(bb.width + 16, bb.height + 9).radius(5).move(bb.x - 8, bb.y - 4.5)
    .fill('#fff').opacity(0.9).back();
}

/* ---------- master update ---------- */
function update() {
  drawVectors(PA);
  drawVectors(PB);
  drawAnnotation();

  PA.root.opacity(state.isolate === 'B' ? 0.18 : 1);
  PB.root.opacity(state.isolate === 'A' ? 0.18 : 1);
  PA.blockB.opacity(state.isolate === 'A' ? 0.28 : 1);
  PB.blockA.opacity(state.isolate === 'B' ? 0.28 : 1);
  PA.cap.opacity(state.isolate === 'B' ? 0.4 : 1);
  PB.cap.opacity(state.isolate === 'A' ? 0.4 : 1);

  var keys = PAIR[state.pair];
  [PA, PB].forEach(function (P) {
    for (var k in P.rows) P.rows[k].bg.opacity(keys.indexOf(k) >= 0 ? 0.35 : 0);
  });

  var bA = document.getElementById('isoABtn'), bB = document.getElementById('isoBBtn'),
    bN = document.getElementById('isoNoneBtn');
  if (bA) bA.className = (state.isolate === 'A') ? 'active' : '';
  if (bB) bB.className = (state.isolate === 'B') ? 'active' : '';
  if (bN) bN.className = (state.isolate === null) ? 'active' : '';

  var sv = document.getElementById('slidingVal');
  if (sv) sv.textContent = state.flip
    ? 'A tends to slide DOWN over B: f\u20D7 BA now points up the slope and f\u20D7 AB down. Only the A\u2013B pair flips \u2014 f\u20D7 B comes from a different contact.'
    : 'Default (the textbook figure): the cord pulls A, so A tends to slide UP over B \u2014 friction from B on A points down the slope, and f\u20D7 AB on B points up.';
}

/* ---------- interactions ---------- */
function setIsolate(v) { state.isolate = v; update(); }
function trigger_isolateA() { setIsolate('A'); }
function trigger_isolateB() { setIsolate('B'); }
function trigger_isolateNone() { setIsolate(null); }
function toggle_contactPair(v) { state.pair = v; update(); }
function toggle_slidingTendency(v) { state.flip = (v === 'down'); update(); }
function showKeyInsight() {
  showPopup('Key insight',
    'Third-law partners like N\u20D7\u2009BA and N\u20D7\u2009AB are equal in magnitude and opposite in direction, but they always appear on different free-body diagrams. That is exactly why isolating one body at a time is the only reliable way to keep them straight \u2014 forces on different bodies can never cancel each other.');
}

/* ---------- demo steps ---------- */
var steps = [
  {
    title: 'The whole system',
    narr: 'Two blocks sit stacked on the incline, with a cord pulling block A up the slope. Before drawing any arrows, notice what each body touches: A touches the cord and block B, while B touches A and the incline.',
    st: { isolate: null, pair: 'none', flip: false }
  },
  {
    title: 'Isolate block A',
    narr: 'Click block A: everything else fades, leaving only the four forces acting on A \u2014 the tension T up the slope, the normal force N_BA from B, the friction f_BA from B, and A\u2019s weight w_A straight down.',
    st: { isolate: 'A', pair: 'none', flip: false }
  },
  {
    title: 'Isolate block B',
    narr: 'Click block B instead. B feels five forces: its weight w_B, the incline\u2019s normal N_B and friction f_B, plus the normal N_AB and friction f_AB that block A presses back onto it. The tension never appears \u2014 the cord does not touch B.',
    st: { isolate: 'B', pair: 'none', flip: false }
  },
  {
    title: 'The normal-force pair',
    narr: 'Highlight the normal pair: N_BA pushes A away from the contact surface while N_AB presses into it with equal magnitude. Equal and opposite \u2014 but they live on different free-body diagrams, so they never cancel each other.',
    st: { isolate: null, pair: 'normal', flip: false }
  },
  {
    title: 'The friction pair',
    narr: 'Now highlight the friction pair. The cord makes A tend to slide up over B, so f_BA on A points down the slope while f_AB on B points up the slope. Same contact surface, same magnitude, opposite directions, two different bodies.',
    st: { isolate: null, pair: 'friction', flip: false }
  },
  {
    title: 'Reverse the sliding tendency',
    narr: 'Now suppose gravity wins and A tends to slide DOWN over B. Both arrows of the A\u2013B friction pair swap ends, staying equal and opposite. The normals and the vertical weights are untouched, and f_B is a different contact \u2014 friction direction is set by the relative sliding, not by the picture.',
    st: { isolate: null, pair: 'friction', flip: true }
  }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = (i + steps.length) % steps.length;
  var s = steps[stepIdx];
  state.isolate = s.st.isolate; state.pair = s.st.pair; state.flip = s.st.flip;
  var sel = document.getElementById('contactPairInput'); if (sel) sel.value = state.pair;
  var tsel = document.getElementById('slidingTendencyInput'); if (tsel) tsel.value = state.flip ? 'down' : 'up';
  var nar = document.getElementById('demoNarration'); if (nar) nar.textContent = s.narr;
  var lab = document.getElementById('stepLabel');
  if (lab) lab.textContent = (stepIdx + 1) + ' / ' + steps.length + ' \u00b7 ' + s.title;
  update();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

